def solve(nums):
    if not nums:
        return 0
    num_set = set(nums)
    max_run = 0
    h1 = sorted(num_set)
    for num in h1:
        if num - 1 in num_set:
            continue
        current_run = 1
        next_num = num + 1
        while next_num in num_set:
            current_run += 1
            next_num += 1
        max_run = max(max_run, current_run)
    return max_run

